changeSet.sql:
-- Fourth boot-brick closure: block a concurrent old-binary writer for the -- WHOLE remainder of this transaction before touching anything else. LOCK TABLE nexus.catalog_document_chunks IN ACCESS EXCLUSIVE MODE;
-- RLS toggle, all five tables this changeset's SELECT/UPDATE/DELETE touch. ALTER TABLE nexus.catalog_document_chunks NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.catalog_documents NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks_384 NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks_768 NO FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks_1024 NO FORCE ROW LEVEL SECURITY;
-- Step 1: rows with no collection at all are unresolvable by definition -- -- delete outright, no resolution attempt. RETURNING captured into a temp -- table so the resync below (step 3) knows exactly which docs were touched. CREATE TEMP TABLE t_71gw2_deleted_null ON COMMIT DROP AS WITH del AS ( DELETE FROM nexus.catalog_document_chunks WHERE collection IS NULL RETURNING tenant_id, doc_id ) SELECT DISTINCT tenant_id, doc_id FROM del;
-- Step 2: dangling rows -- a NON-NULL collection that does not actually -- contain the row's chash in any of chunks_384/768/1024. This is exactly -- nexus-c30ew's failure shape (a stamped collection that turns out wrong) -- and exactly what the Phase 5 FK will reject; a re-index regenerates a -- real row. `collection IS NOT NULL` keeps this DISJOINT from step 1's -- already-deleted rows (two data-modifying statements targeting the same -- row inside one transaction is unspecified in PostgreSQL; disjoint sets -- avoids the question entirely). CREATE TEMP TABLE t_71gw2_deleted_dangling ON COMMIT DROP AS WITH del AS ( DELETE FROM nexus.catalog_document_chunks c WHERE c.collection IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.chunks_384 v WHERE v.tenant_id = c.tenant_id AND v.collection = c.collection AND v.chash = c.chash) AND NOT EXISTS (SELECT 1 FROM nexus.chunks_768 v WHERE v.tenant_id = c.tenant_id AND v.collection = c.collection AND v.chash = c.chash) AND NOT EXISTS (SELECT 1 FROM nexus.chunks_1024 v WHERE v.tenant_id = c.tenant_id AND v.collection = c.collection AND v.chash = c.chash) RETURNING tenant_id, doc_id ) SELECT DISTINCT tenant_id, doc_id FROM del;
-- Step 3: documents.chunk_count resync (nexus-mqd6t's two predicates, -- verbatim, for every touched doc only): COUNT scoped to a live parent, -- UPDATE guarded by deleted_at IS NULL so a resync can never write through -- to a tombstone. CREATE TEMP TABLE t_71gw2_touched_docs ON COMMIT DROP AS SELECT tenant_id, doc_id FROM t_71gw2_deleted_null UNION SELECT tenant_id, doc_id FROM t_71gw2_deleted_dangling;
UPDATE nexus.catalog_documents d SET chunk_count = ( SELECT count(*) FROM nexus.catalog_document_chunks cc WHERE cc.tenant_id = d.tenant_id AND cc.doc_id = d.tumbler AND EXISTS ( SELECT 1 FROM nexus.catalog_documents dp WHERE dp.tenant_id = cc.tenant_id AND dp.tumbler = cc.doc_id AND dp.deleted_at IS NULL ) ) FROM t_71gw2_touched_docs td WHERE d.tenant_id = td.tenant_id AND d.tumbler = td.doc_id AND d.deleted_at IS NULL;
-- Step 4: the partial index's predicate becomes vacuous the instant -- collection is NOT NULL (every row satisfies it); converted to plain so a -- caller that stops spelling out `collection IS NOT NULL` cannot silently -- lose the index to a seq scan (PostgreSQL proves partial-index usability -- from the query's own clauses, not the column constraint). DROP INDEX IF EXISTS nexus.idx_catalog_chunks_collection; CREATE INDEX idx_catalog_chunks_collection ON nexus.catalog_document_chunks (tenant_id, collection);
-- Unfailable by construction: every remaining collection-IS-NULL row was -- just deleted above, so this ALTER cannot reject a residual row -- no -- manual per-deployment remediation, no operator sequencing. ALTER TABLE nexus.catalog_document_chunks ALTER COLUMN collection SET NOT NULL;
ALTER TABLE nexus.chunks_1024 FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks_768 FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.chunks_384 FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.catalog_documents FORCE ROW LEVEL SECURITY; ALTER TABLE nexus.catalog_document_chunks FORCE ROW LEVEL SECURITY;

changeSet.rollback:
DROP INDEX IF EXISTS nexus.idx_catalog_chunks_collection;
CREATE INDEX idx_catalog_chunks_collection
    ON nexus.catalog_document_chunks (tenant_id, collection)
    WHERE collection IS NOT NULL;
ALTER TABLE nexus.catalog_document_chunks ALTER COLUMN collection DROP NOT NULL;
